-- Aarogya India — catalog seed (domains, certifications, questions, options)
--
-- GENERATED FILE — do not edit by hand.
-- Source: app/src/data/seed.ts
-- Regenerate: cd app && node scripts/gen-seed-sql.mjs
--
-- The catalog lived only in TypeScript, which the local browser backend reads
-- directly. Supabase had the tables but no rows, so a hosted deployment showed
-- an empty certification directory. This migration loads the same catalog.
--
-- Safe to re-run: every statement upserts on the primary key.
-- Run with: supabase db push   (or paste into the Supabase SQL editor)

begin;

-- ------------------------------------------------------------- domains
on conflict (id) do update set
  slug = excluded.slug,
  name = excluded.name,
  description = excluded.description,
  name_hi = excluded.name_hi,
  description_hi = excluded.description_hi,
  icon = excluded.icon,
  sort_order = excluded.sort_order,
  is_active = excluded.is_active;

-- ------------------------------------------------------ certifications
on conflict (id) do update set
  domain_id = excluded.domain_id,
  slug = excluded.slug,
  title = excluded.title,
  short_desc = excluded.short_desc,
  description = excluded.description,
  eligibility = excluded.eligibility,
  title_hi = excluded.title_hi,
  short_desc_hi = excluded.short_desc_hi,
  description_hi = excluded.description_hi,
  eligibility_hi = excluded.eligibility_hi,
  duration_sec = excluded.duration_sec,
  question_count = excluded.question_count,
  pass_score_pct = excluded.pass_score_pct,
  topics = excluded.topics,
  is_active = excluded.is_active,
  popularity = excluded.popularity,
  created_at = excluded.created_at;

-- ----------------------------------------------------------- questions
on conflict (id) do update set
  certification_id = excluded.certification_id,
  domain_id = excluded.domain_id,
  topic = excluded.topic,
  difficulty = excluded.difficulty,
  qtype = excluded.qtype,
  body = excluded.body,
  body_hi = excluded.body_hi,
  explanation = excluded.explanation,
  explanation_hi = excluded.explanation_hi,
  is_active = excluded.is_active;

-- ---------------------------------------------------- question_options
on conflict (id) do update set
  question_id = excluded.question_id,
  label = excluded.label,
  label_hi = excluded.label_hi,
  is_correct = excluded.is_correct,
  sort_order = excluded.sort_order;

commit;

