  ('cert-web-development', 'dom-tech', 'web-development', 'Web Development', 'Build modern, accessible, responsive web applications.', 'Build modern, accessible, responsive web applications. This certification validates practical, job-ready knowledge across HTML & CSS, JavaScript, HTTP & APIs, Accessibility. The assessment is objective, timed and automatically scored.', 'Open to all learners. No prior credential required. A basic familiarity with the subject is recommended.', 'वेब विकास', 'आधुनिक, सुलभ, उत्तरदायी वेब एप्लिकेशन बनाएं।', 'आधुनिक, सुलभ, उत्तरदायी वेब एप्लिकेशन बनाएं। यह प्रमाणपत्र HTML और CSS, जावास्क्रिप्ट, HTTP और APIs, पहुंच में व्यावहारिक, काम-तैयार ज्ञान को मान्य करता है। आकलन उद्देश्य, समयबद्ध और स्वचालित रूप से स्कोर किया जाता है।', 'सभी शिक्षार्थियों के लिए खुला। कोई पूर्व क्रेडेंशियल की आवश्यकता नहीं। विषय से बुनियादी परिचितता की सिफारिश की जाती है।', 420, 10, 60, array['HTML & CSS', 'JavaScript', 'HTTP & APIs', 'Accessibility']::text[], true, 98, '2025-12-04T00:00:00.000Z'),
  ('cert-data-analytics', 'dom-tech', 'data-analytics', 'Data Analytics', 'Turn raw data into clear, actionable insight.', 'Turn raw data into clear, actionable insight. This certification validates practical, job-ready knowledge across Statistics, Spreadsheets, SQL, Visualization. The assessment is objective, timed and automatically scored.', 'Open to all learners. No prior credential required. A basic familiarity with the subject is recommended.', 'डेटा विश्लेषण', 'कच्चे डेटा को स्पष्ट, कार्यशील अंतर्दृष्टि में बदलें।', 'कच्चे डेटा को स्पष्ट, कार्यशील अंतर्दृष्टि में बदलें। यह प्रमाणपत्र सांख्यिकी, स्प्रेडशीट, SQL, दृश्य में व्यावहारिक, काम-तैयार ज्ञान को मान्य करता है। आकलन उद्देश्य, समयबद्ध और स्वचालित रूप से स्कोर किया जाता है।', 'सभी शिक्षार्थियों के लिए खुला। कोई पूर्व क्रेडेंशियल की आवश्यकता नहीं। विषय से बुनियादी परिचितता की सिफारिश की जाती है।', 420, 10, 60, array['Statistics', 'Spreadsheets', 'SQL', 'Visualization']::text[], true, 95, '2025-12-05T00:00:00.000Z'),
