  ('cert-people-management', 'dom-hr', 'people-management', 'People Management', 'Motivate, coach and retain high-performing teams.', 'Motivate, coach and retain high-performing teams. This certification validates practical, job-ready knowledge across Motivation, Feedback, Performance, Retention. The assessment is objective, timed and automatically scored.', 'Open to all learners. No prior credential required. A basic familiarity with the subject is recommended.', null, null, null, null, 420, 10, 60, array['Motivation', 'Feedback', 'Performance', 'Retention']::text[], true, 85, '2025-12-27T00:00:00.000Z'),
  ('cert-panchkarma-therapy', 'dom-ayurveda', 'panchkarma-therapy', 'Panchkarma Therapy Fundamentals', 'Master the five classical purification therapies of Ayurveda.', 'Master the five classical purification therapies of Ayurveda. This certification validates practical, job-ready knowledge across Vata Therapies, Pitta Therapies, Kapha Therapies, Post-Therapy Care. The assessment is objective, timed and automatically scored.', 'Open to all learners. No prior credential required. A basic familiarity with the subject is recommended.', 'पंचकर्म चिकित्सा मौलिकताएं', 'आयुर्वेद की पाँच शास्त्रीय शुद्धिकरण चिकित्सा में महारत प्राप्त करें।', 'आयुर्वेद की पाँच शास्त्रीय शुद्धिकरण चिकित्सा में महारत प्राप्त करें। यह प्रमाणपत्र वात चिकित्सा, पित्त चिकित्सा, कफ चिकित्सा, चिकित्सा-पश्चात देखभाल में व्यावहारिक, काम-तैयार ज्ञान को मान्य करता है। आकलन उद्देश्य, समयबद्ध और स्वचालित रूप से स्कोर किया जाता है।', 'सभी शिक्षार्थियों के लिए खुला। कोई पूर्व क्रेडेंशियल की आवश्यकता नहीं। विषय से बुनियादी परिचितता की सिफारिश की जाती है।', 420, 10, 60, array['Vata Therapies', 'Pitta Therapies', 'Kapha Therapies', 'Post-Therapy Care']::text[], true, 92, '2025-12-28T00:00:00.000Z'),
  ('cert-marma-therapy', 'dom-ayurveda', 'marma-therapy', 'Marma Therapy & Points', 'Understand vital energy points and therapeutic applications.', 'Understand vital energy points and therapeutic applications. This certification validates practical, job-ready knowledge across Marma Locations, Point Classification, Treatment Protocols, Safety Guidelines. The assessment is objective, timed and automatically scored.', 'Open to all learners. No prior credential required. A basic familiarity with the subject is recommended.', 'मर्म चिकित्सा और बिंदु', 'महत्वपूर्ण ऊर्जा बिंदुओं और चिकित्सकीय अनुप्रयोग को समझें।', 'महत्वपूर्ण ऊर्जा बिंदुओं और चिकित्सकीय अनुप्रयोग को समझें। यह प्रमाणपत्र मर्म स्थान, बिंदु वर्गीकरण, चिकित्सा प्रोटोकॉल, सुरक्षा दिशानिर्देशों में व्यावहारिक, काम-तैयार ज्ञान को मान्य करता है। आकलन उद्देश्य, समयबद्ध और स्वचालित रूप से स्कोर किया जाता है।', 'सभी शिक्षार्थियों के लिए खुला। कोई पूर्व क्रेडेंशियल की आवश्यकता नहीं। विषय से बुनियादी परिचितता की सिफारिश की जाती है।', 420, 10, 60, array['Marma Locations', 'Point Classification', 'Treatment Protocols', 'Safety Guidelines']::text[], true, 88, '2025-12-29T00:00:00.000Z'),
  ('cert-ayurvedic-nutrition', 'dom-ayurveda', 'ayurvedic-nutrition', 'Ayurvedic Diet & Nutrition', 'Apply doshas and food principles for personalized wellness.', 'Apply doshas and food principles for personalized wellness. This certification validates practical, job-ready knowledge across Dosha Constitution, Food Properties, Seasonal Eating, Digestive Health. The assessment is objective, timed and automatically scored.', 'Open to all learners. No prior credential required. A basic familiarity with the subject is recommended.', 'आयुर्वेदिक आहार और पोषण', 'व्यक्तिगत कल्याण के लिए दोष और खाद्य सिद्धांत लागू करें।', 'व्यक्तिगत कल्याण के लिए दोष और खाद्य सिद्धांत लागू करें। यह प्रमाणपत्र दोष संविधान, खाद्य गुण, मौसमी खाने, पाचन स्वास्थ्य में व्यावहारिक, काम-तैयार ज्ञान को मान्य करता है। आकलन उद्देश्य, समयबद्ध और स्वचालित रूप से स्कोर किया जाता है।', 'सभी शिक्षार्थियों के लिए खुला। कोई पूर्व क्रेडेंशियल की आवश्यकता नहीं। विषय से बुनियादी परिचितता की सिफारिश की जाती है।', 420, 10, 60, array['Dosha Constitution', 'Food Properties', 'Seasonal Eating', 'Digestive Health']::text[], true, 90, '2025-12-30T00:00:00.000Z'),
  ('cert-ayurvedic-herbs', 'dom-ayurveda', 'ayurvedic-herbs', 'Ayurvedic Herbal Medicine', 'Identify and apply therapeutic herbs in Ayurvedic practice.', 'Identify and apply therapeutic herbs in Ayurvedic practice. This certification validates practical, job-ready knowledge across Herb Properties, Formulations, Preparation Methods, Interactions & Safety. The assessment is objective, timed and automatically scored.', 'Open to all learners. No prior credential required. A basic familiarity with the subject is recommended.', 'आयुर्वेदिक औषधि चिकित्सा', 'आयुर्वेदिक अभ्यास में चिकित्सकीय जड़ी-बूटियों की पहचान और अनुप्रयोग करें।', 'आयुर्वेदिक अभ्यास में चिकित्सकीय जड़ी-बूटियों की पहचान और अनुप्रयोग करें। यह प्रमाणपत्र जड़ी-बूटी गुण, तैयारी, तैयारी विधि, अंतःक्रिया और सुरक्षा में व्यावहारिक, काम-तैयार ज्ञान को मान्य करता है। आकलन उद्देश्य, समयबद्ध और स्वचालित रूप से स्कोर किया जाता है।', 'सभी शिक्षार्थियों के लिए खुला। कोई पूर्व क्रेडेंशियल की आवश्यकता नहीं। विषय से बुनियादी परिचितता की सिफारिश की जाती है।', 420, 10, 60, array['Herb Properties', 'Formulations', 'Preparation Methods', 'Interactions & Safety']::text[], true, 85, '2025-12-31T00:00:00.000Z')
